#include "stv/source_lab.hpp"
#include "../src/source_states.hpp"
#include <fstream>
#include <iostream>
#include <memory>
#include <stdexcept>
#include <string>
#include <vector>
using namespace stv;
static unsigned groups=0;static u64 checks=0;
#define CHECK(x) do{++checks;if(!(x))throw std::runtime_error(std::string(__FILE__)+":"+std::to_string(__LINE__)+": " #x);}while(false)
static void ok(Status s){if(!s)throw std::runtime_error(s.message?s.message:"Failed status");++checks;}
template<class F>void group(const char* name,F f){f();++groups;std::cout<<"PASS "<<name<<'\n';}
static std::vector<unsigned> frames(unsigned gate,unsigned duration,unsigned& elapsed,unsigned& sounds){SourceDoors s;DoorTask t{u8(gate),duration};std::vector<unsigned> out;elapsed=sounds=0;for(unsigned n=0;n<1000;++n){DoorEvent e;ok(source_door_step(s,t,false,e));sounds+=e.sound;if(e.redraw)out.push_back(e.frame);if(e.done){CHECK(s.timer[gate-1]==0);CHECK(s.view[gate-1]==1);return out;}elapsed+=e.sleep;}throw std::runtime_error("Door failed to close");}
int main(int argc,char**argv){try{
 if(argc!=2)throw std::runtime_error("Pass source.stva");std::ifstream f(argv[1],std::ios::binary);std::vector<u8> bytes((std::istreambuf_iterator<char>(f)),{});auto pack=std::make_unique<SourcePack>();ok(pack->open({bytes.data(),bytes.size()}));
 group("ROBODOOR left/right asymmetry and exact SLEEP durations",[]{unsigned ticks,sounds;CHECK((frames(1,3,ticks,sounds)==std::vector<unsigned>{2,3,4,4,3,2,1}));CHECK(ticks==31&&sounds==2);CHECK((frames(2,3,ticks,sounds)==std::vector<unsigned>{1,2,3,3,2,1}));CHECK(ticks==28&&sounds==2);});
 group("Top door redraws both halves through terminal frame zero then SLEEP 1",[]{unsigned ticks,sounds;CHECK((frames(3,3,ticks,sounds)==std::vector<unsigned>{1,2,3,4,5,6,7,8,8,7,6,5,4,3,2,1,0}));CHECK(ticks==27&&sounds==2);});
 group("HALT holds countdown but does not freeze opening frames",[]{SourceDoors s;DoorTask t{1,5};DoorEvent e;for(unsigned i=0;i<4;++i)ok(source_door_step(s,t,true,e));CHECK(t.phase==DoorPhase::holding&&s.timer[0]==5&&s.view[0]==4);for(unsigned i=0;i<100;++i){ok(source_door_step(s,t,true,e));CHECK(e.sleep==5&&!e.redraw&&s.timer[0]==5);}ok(source_door_step(s,t,false,e));CHECK(s.timer[0]==4);});
 group("Held-open signed byte FF remains open and finite requests replace it",[]{SourceDoors s;DoorTask t{2,0xffffffffu};DoorEvent e;for(unsigned i=0;i<100;++i)ok(source_door_step(s,t,false,e));CHECK(s.timer[1]==255&&t.phase==DoorPhase::holding);DoorRequest r;ok(source_gate_request(s,2,8,false,true,r));CHECK(s.timer[1]==8&&!r.create);ok(source_gate_request(s,2,6,false,true,r));CHECK(s.timer[1]==8);ok(source_gate_request(s,2,10,false,true,r));CHECK(s.timer[1]==10);ok(source_gate_request(s,2,0xffffff80u,false,true,r));CHECK(s.timer[1]==128);});
 group("GATES extension uses signed MOVB and incoming bit 7, not unsigned max",[]{for(unsigned old=1;old<256;++old)for(unsigned incoming:{0u,1u,5u,127u,128u,255u,256u,0xffffff7fu}){SourceDoors s;s.timer[0]=u8(old);DoorRequest out;ok(source_gate_request(s,1,incoming,false,true,out));const auto expected=(incoming&128)||signed32(incoming)>=signed8(u8(old))?u8(incoming):u8(old);CHECK(s.timer[0]==expected&&!out.create);}});
 group("Pending requests and closed-image recovery retain source EXISTP asymmetry",[]{SourceDoors s;DoorRequest r;ok(source_gate_request(s,1,10,false,true,r));CHECK(r.create&&s.timer[0]==0);ok(source_gate_request(s,1,10,false,true,r));CHECK(r.create);s.timer[0]=3;ok(source_gate_request(s,1,2,true,true,r));CHECK(!r.create);ok(source_gate_request(s,1,2,true,false,r));CHECK(r.create);s.timer[2]=3;ok(source_gate_request(s,3,2,true,true,r));CHECK(r.create);ok(source_gate_request(s,3,2,false,false,r));CHECK(!r.create);});
 group("Bottom gate has sound only; bad gate indices fail explicitly",[]{SourceDoors s;s.timer[0]=17;DoorRequest r;ok(source_gate_request(s,4,100,false,false,r));CHECK(r.sound_only&&!r.create&&s.timer[0]==17);CHECK(!source_gate_request(s,0,5,false,false,r));CHECK(!source_gate_request(s,5,5,false,false,r));DoorTask t{4,5};DoorEvent e;CHECK(!source_door_step(s,t,false,e));});
 group("Zero and one countdowns reproduce signed-byte underflow instead of invented close",[]{for(unsigned n:{0u,1u}){SourceDoors s;DoorTask t{1,n};DoorEvent e;for(unsigned i=0;i<50;++i)ok(source_door_step(s,t,false,e));CHECK(s.timer[0]==255&&t.phase==DoorPhase::holding);}});
 group("Source-linked 64 block headers / 66 placements / palettes and promotion",[&]{auto lab=std::make_unique<SourceLab>();ok(lab->load(*pack));ok(lab->reset(1,1,0,true));CHECK(source_arena_header_count==64&&source_arena_placement_count==66);unsigned promoted=0;for(unsigned i=0;i<source_arena_placement_count;++i){auto p=source_arena_placements[i];if((p.flags>>8)>=100)++promoted;}CHECK(lab->objects.count==promoted);for(unsigned gate=0;gate<4;++gate){auto h=lab->door_objects[gate];CHECK(h<420);const auto& s=lab->objects.cells[h].sprite;CHECK(s.raw_image&&s.palette_view==&source_arena_palettes[0]);}CHECK(lab->objects.cells[lab->door_objects[0]].sprite.position.x==11u<<16);CHECK(lab->objects.cells[lab->door_objects[0]].sprite.position.y==95u<<16);CHECK(lab->objects.cells[lab->door_objects[1]].sprite.position.x==368u<<16);CHECK(lab->objects.cells[lab->door_objects[2]].sprite.position.x==158u<<16);CHECK(lab->objects.cells[lab->door_objects[3]].sprite.position.x==194u<<16);CHECK(source_arena_foreground_z(118)==18&&source_arena_foreground_z(120)==130&&source_arena_foreground_z(127)==255);ok(lab->validate());});
 group("Actual gate objects preserve linked palette ownership and flip anchors",[&]{auto lab=std::make_unique<SourceLab>();ok(lab->load(*pack));ok(lab->reset(1,1,0,true));u32 x[4],y[4];for(unsigned i=0;i<4;++i)ok(sprite_anchor(lab->objects.cells[lab->door_objects[i]].sprite,x[i],y[i]));for(unsigned gate=1;gate<=3;++gate)ok(lab->open_source_gate(gate,3));for(unsigned tick=0;tick<80;++tick){ok(lab->tick({}));ok(lab->validate());for(unsigned i=0;i<4;++i){auto& s=lab->objects.cells[lab->door_objects[i]].sprite;u32 a,b;ok(sprite_anchor(s,a,b));CHECK(a==x[i]&&b==y[i]&&s.palette_view==&source_arena_palettes[0]);}}CHECK(lab->stats.door_completions==3&&lab->stats.door_processes==3&&lab->stats.door_frames==30);for(unsigned i=0;i<3;++i)CHECK(lab->doors.timer[i]==0);});
 group("Real player re-entry reaches native gate process, not an audit counter",[&]{auto lab=std::make_unique<SourceLab>();ok(lab->load(*pack));ok(lab->reset(1,1,0,true));ok(lab->tick({}));auto& p=lab->players[0];p.life.dead=0x8600;p.life.immunity=0;ok(lab->processes.transfer(p.torso_process,source_state::player_all_die,nullptr));for(unsigned t=0;t<300&&lab->stats.door_frames==0;++t)ok(lab->tick({}));CHECK(p.gate_requests==1&&lab->stats.gate_requests==1&&lab->stats.door_frames>0&&lab->doors.timer[0]==10);ok(lab->validate());});
 group("Linked arena and independently scheduled doors reproduce state/pixels",[&]{auto a=std::make_unique<SourceLab>(),b=std::make_unique<SourceLab>();ok(a->load(*pack));ok(b->load(*pack));ok(a->reset(3,2,0,true));ok(b->reset(3,2,0,true));std::vector<u32> pa(lab_width*lab_height),pb(pa.size());for(unsigned t=0;t<700;++t){if(t%70==0){ok(a->open_source_gate(t/70%4+1,8));ok(b->open_source_gate(t/70%4+1,8));}a->halted=b->halted=(t%100)>75;ok(a->tick({}));ok(b->tick({}));ok(a->validate());ok(b->validate());auto da=a->state_digest(),db=b->state_digest();CHECK(equal(da.bytes,db.bytes,32));if(t%17==0){ok(a->draw({pa.data(),lab_width,lab_height,lab_width,pa.size()}));ok(b->draw({pb.data(),lab_width,lab_height,lab_width,pb.size()}));CHECK(pa==pb);}}});
 std::cout<<"PASS "<<groups<<" gate/linked-arena groups, "<<checks<<" assertions\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
